import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Triggers & the Envelope","description":"","frontmatter":{},"headers":[],"relativePath":"guide/triggers.md","filePath":"guide/triggers.md","lastUpdated":1792495823000}'),t={name:"guide/triggers.md"};function p(l,s,r,c,i,d){return n(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="triggers-the-envelope" tabindex="-1">Triggers &amp; the Envelope <a class="header-anchor" href="#triggers-the-envelope" aria-label="Permalink to &quot;Triggers &amp; the Envelope&quot;">​</a></h1><p>A trigger describes how a run of an agent can start. At intake every trigger becomes the same shape, a <code>TriggerEnvelope</code>, and <code>engine.dispatch()</code> turns the envelope into a <code>queued</code> run.</p><h2 id="trigger-definitions" tabindex="-1">Trigger definitions <a class="header-anchor" href="#trigger-definitions" aria-label="Permalink to &quot;Trigger definitions&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> triage = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Triage the issue in the trigger payload.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    triggers: [</span></span>
<span class="line"><span style="color:#E6DFDE;">        http(), </span><span style="color:#958A8B;">// id &#39;http&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">        webhook({ path: </span><span style="color:#E7C58C;">&#39;/issues&#39;</span><span style="color:#E6DFDE;"> }), </span><span style="color:#958A8B;">// id &#39;webhook:/issues&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">        cron(</span><span style="color:#E7C58C;">&#39;*/30 * * * *&#39;</span><span style="color:#E6DFDE;">, { overlap: </span><span style="color:#E7C58C;">&#39;skip&#39;</span><span style="color:#E6DFDE;"> }), </span><span style="color:#958A8B;">// id &#39;cron:*/30 * * * *&#39;</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Builder</th><th>Source</th><th>Id</th><th>Options</th></tr></thead><tbody><tr><td><code>http(opts?)</code></td><td><code>http</code></td><td><code>http</code></td><td><code>schema?</code>: a Standard Schema for the payload. At most one per agent; REST, the UI and MCP start runs through it</td></tr><tr><td><code>webhook(opts)</code></td><td><code>webhook</code></td><td><code>webhook:&lt;path&gt;</code></td><td><code>path</code> (starts with <code>/</code>), <code>schema?</code>, <code>idempotencyKey?</code>, <code>concurrencyKey?</code>. Many per agent</td></tr><tr><td><code>cron(expression, opts?)</code></td><td><code>cron</code></td><td><code>cron:&lt;expression&gt;</code></td><td><code>timezone?</code>, <code>overlap?</code> (<code>skip</code> by default, <code>queue-one</code>, <code>allow</code>), <code>payload?</code></td></tr></tbody></table><p><code>cron()</code> validates the expression (and timezone) with cron-parser and throws <code>InvalidAgentDefinitionError</code> for an invalid one; <code>webhook()</code> throws it for a path that does not start with <code>/</code>. Trigger ids must be unique per agent, so an agent declares <code>http()</code> at most once.</p><p>A <code>TriggerDefinition</code> may also carry <code>concurrencyKey(payload)</code> and <code>idempotencyKey(payload)</code> functions (<code>webhook()</code> copies them from its options). They are meant for the intake packages, which compute the envelope keys from a payload.</p><div class="warning custom-block"><p class="custom-block-title">Firing triggers is not in core</p><p>In <code>@chamberu/core</code>, <code>engine.dispatch()</code> is the only way a run starts. The trigger definitions describe intent; nothing in core fires a cron expression or listens on an HTTP path. <a href="/guide/scheduler"><code>@chamberu/scheduler</code></a> fires <code>cron()</code> triggers (with per-tick locks and the overlap policy); <a href="/guide/http"><code>@chamberu/http</code></a> serves <code>http()</code> triggers over REST and MCP and <code>webhook()</code> triggers at <code>/hooks/:agent&lt;path&gt;</code>.</p></div><h2 id="the-envelope" tabindex="-1">The envelope <a class="header-anchor" href="#the-envelope" aria-label="Permalink to &quot;The envelope&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">/*</span></span>
<span class="line"><span style="color:#958A8B;"> * Copyright (c) 2026.</span></span>
<span class="line"><span style="color:#958A8B;"> * Author Peter Placzek (tada5hi)</span></span>
<span class="line"><span style="color:#958A8B;"> * For the full copyright and license information,</span></span>
<span class="line"><span style="color:#958A8B;"> * view the LICENSE file that was distributed with this source code.</span></span>
<span class="line"><span style="color:#958A8B;"> */</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> { Artifact } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;../artifact/types.ts&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> TriggerSource = </span><span style="color:#E7C58C;">&#39;cron&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;github&#39;</span><span style="color:#E6DFDE;"> | </span><span style="color:#E7C58C;">&#39;mcp&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> TriggerDefinition&lt;P = unknown&gt; = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: TriggerSource;</span></span>
<span class="line"><span style="color:#958A8B;">    /** Unique within an agent, e.g. &#39;cron:*\\/30 * * * *&#39;. */</span></span>
<span class="line"><span style="color:#E6DFDE;">    id: string;</span></span>
<span class="line"><span style="color:#958A8B;">    /** Source-specific (cron: { expression, timezone?, overlap }). */</span></span>
<span class="line"><span style="color:#E6DFDE;">    options: Record&lt;string, unknown&gt;;</span></span>
<span class="line"><span style="color:#958A8B;">    // method signatures (bivariant): a TriggerDefinition&lt;P&gt; fits AgentDefinition.triggers</span></span>
<span class="line"><span style="color:#E6DFDE;">    concurrencyKey?(payload: P): string | undefined;</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey?(payload: P): string | undefined;</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">/**</span></span>
<span class="line"><span style="color:#958A8B;"> * Who started a run (or answered an approval), as an authenticator resolved</span></span>
<span class="line"><span style="color:#958A8B;"> * it: a snapshot of identity and grants taken at dispatch, never a token.</span></span>
<span class="line"><span style="color:#958A8B;"> * Revoking a grant later does not reach a run that already holds it.</span></span>
<span class="line"><span style="color:#958A8B;"> */</span></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> Invoker = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    id: string;</span></span>
<span class="line"><span style="color:#958A8B;">    /**</span></span>
<span class="line"><span style="color:#958A8B;">     * The authenticator&#39;s label: \`@chamberu/http\`&#39;s staticTokens() sets</span></span>
<span class="line"><span style="color:#958A8B;">     * &#39;token&#39; and authup() sets &#39;authup&#39;; oidc() keeps the kind its</span></span>
<span class="line"><span style="color:#958A8B;">     * \`principal\` mapper returns (the docs use &#39;oidc&#39;); a custom authenticator</span></span>
<span class="line"><span style="color:#958A8B;">     * or a direct dispatch may use its own (e.g. &#39;user&#39;).</span></span>
<span class="line"><span style="color:#958A8B;">     */</span></span>
<span class="line"><span style="color:#E6DFDE;">    kind: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    name?: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    permissions: </span><span style="color:#FF7B84;">readonly</span><span style="color:#E6DFDE;"> string[];</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> type</span><span style="color:#E6DFDE;"> TriggerEnvelope&lt;P = unknown&gt; = {</span></span>
<span class="line"><span style="color:#E6DFDE;">    id: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: TriggerSource;</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: P;</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey?: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    concurrencyKey?: string;</span></span>
<span class="line"><span style="color:#E6DFDE;">    thread?: string;</span></span>
<span class="line"><span style="color:#958A8B;">    /** Files the run was started with, stored as artifacts of the run; the model gets them as file parts. */</span></span>
<span class="line"><span style="color:#E6DFDE;">    attachments?: Artifact[];</span></span>
<span class="line"><span style="color:#958A8B;">    /**</span></span>
<span class="line"><span style="color:#958A8B;">     * Who started the run; only ever set from an authenticator (never from a</span></span>
<span class="line"><span style="color:#958A8B;">     * payload). Absent for cron and webhook runs. With an invoker the</span></span>
<span class="line"><span style="color:#958A8B;">     * idempotency key is scoped to it, so only the same invoker&#39;s dispatch</span></span>
<span class="line"><span style="color:#958A8B;">     * is deduplicated (and gets its own first run).</span></span>
<span class="line"><span style="color:#958A8B;">     */</span></span>
<span class="line"><span style="color:#E6DFDE;">    invoker?: Invoker;</span></span>
<span class="line"><span style="color:#E6DFDE;">    receivedAt: Date;</span></span>
<span class="line"><span style="color:#E6DFDE;">};</span></span></code></pre></div><p><code>dispatch()</code> takes the envelope without <code>id</code> and <code>receivedAt</code>; it fills in a random UUID and the current time. <code>trigger</code> is the trigger id (<code>&#39;http&#39;</code>, <code>&#39;webhook:/issues&#39;</code>, ...). <code>source</code> is one of <code>cron</code>, <code>http</code>, <code>webhook</code>, <code>github</code> or <code>mcp</code> (a run started through <code>http()</code> over MCP has <code>trigger: &#39;http&#39;</code> and <code>source: &#39;mcp&#39;</code>).</p><p>The engine renders the source, trigger id and payload as a JSON block and makes it the run&#39;s first user message. The model sees exactly that; put what it needs into the payload.</p><p><code>thread</code> is stored on the run. Loading the history of earlier runs of the same thread is planned for the mail digest milestone.</p><p><code>invoker</code> is who started the run. Only an intake layer sets it, from its authenticated caller (<code>@chamberu/http</code> fills it from the principal), never from a payload. It is not part of the rendered block, so the model never sees it. See <a href="/guide/tools#restricting-tools-per-invoker">Restricting tools per invoker</a>.</p><h2 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h2><p><code>dispatch()</code> also takes files for the model, <code>attachments: [{ mediaType, filename?, data }]</code> with <code>data</code> a <code>Uint8Array</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> withFile = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#E6DFDE;">, issue: </span><span style="color:#E7C58C;">43</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">    // stored as artifacts of the run; the model gets them as file parts</span></span>
<span class="line"><span style="color:#E6DFDE;">    attachments: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">        mediaType: </span><span style="color:#E7C58C;">&#39;image/png&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        filename: </span><span style="color:#E7C58C;">&#39;crash.png&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        data: </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Uint8Array(</span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> readFile(</span><span style="color:#E7C58C;">&#39;crash.png&#39;</span><span style="color:#E6DFDE;">)),</span></span>
<span class="line"><span style="color:#E6DFDE;">    }],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> run = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.getRun(withFile.runId);</span></span>
<span class="line"><span style="color:#E6DFDE;">run?.trigger.attachments; </span><span style="color:#958A8B;">// [{ id, runId, agent, mediaType: &#39;image/png&#39;, filename: &#39;crash.png&#39;, size, createdAt }]</span></span></code></pre></div><p>Each attachment is checked before anything is written (<code>mediaType</code> of the form <code>type/subtype</code> without parameters, <code>data</code> a <code>Uint8Array</code>; <code>ValidationError</code> otherwise), then stored as an <a href="/guide/agents#files">artifact</a> of the run, after the idempotency check (a deduplicated dispatch stores nothing) and before the run is created. The run&#39;s <code>trigger.attachments</code> holds their metadata. The first user message then carries the rendered envelope as text followed by one file part per attachment, so a model that reads images or PDFs gets them directly. Attachment ids are derived from the run id and the position (<code>&lt;runId&gt;.0000</code>, <code>&lt;runId&gt;.0001</code>, ...), so the run&#39;s artifacts list in the order they were given. A crash between storing the files and creating the run leaves orphan artifacts; nothing purges them yet. Two dispatches that race to create the run of the same reserved idempotency key (its first run was never created) write to the same ids, so the second write of each file is a no-op and the run names exactly the files that were stored; only a racing dispatch with more files than the winner leaves its extra files listed among the run&#39;s artifacts.</p><p>Over HTTP, <code>POST /agents/:name/runs</code> takes the same list with <code>data</code> as base64 (see <a href="/guide/http#files">HTTP API</a>).</p><h2 id="idempotency-keys" tabindex="-1">Idempotency keys <a class="header-anchor" href="#idempotency-keys" aria-label="Permalink to &quot;Idempotency keys&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> first = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: </span><span style="color:#E7C58C;">&#39;webhook:/issues&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#E6DFDE;">, issue: </span><span style="color:#E7C58C;">42</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">    // a redelivery with the same key returns the same run</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey: </span><span style="color:#E7C58C;">&#39;delivery-7f3a&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // one run at a time per issue</span></span>
<span class="line"><span style="color:#E6DFDE;">    concurrencyKey: </span><span style="color:#E7C58C;">&#39;acme/app#42&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> again = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#E6DFDE;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    trigger: </span><span style="color:#E7C58C;">&#39;webhook:/issues&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    source: </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#E6DFDE;">, issue: </span><span style="color:#E7C58C;">42</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">    idempotencyKey: </span><span style="color:#E7C58C;">&#39;delivery-7f3a&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">again.runId === first.runId; </span><span style="color:#958A8B;">// true</span></span>
<span class="line"><span style="color:#E6DFDE;">again.deduplicated; </span><span style="color:#958A8B;">// true</span></span></code></pre></div><p>With an <code>idempotencyKey</code>, <code>dispatch()</code> claims the key in the store under the scope <code>&lt;agent&gt;:&lt;source&gt;</code> (for example <code>triage:webhook</code>) for 7 days. The first dispatch creates the run. Every later dispatch with the same agent, source and key returns the existing run id with <code>deduplicated: true</code>, and no new run is created.</p><p>A dispatch with an <a href="#the-envelope">invoker</a> claims the key under <code>&lt;agent&gt;:&lt;source&gt;:&lt;kind&gt;:&lt;id&gt;</code> instead (<code>kind</code> and <code>id</code> URI-encoded). Keys are then per invoker: the same invoker&#39;s retry is deduplicated, while another invoker sending the same key gets a run of its own and never learns about the first.</p><p>Use a key that is stable across redeliveries: a GitHub delivery id, a cron job plus its scheduled time, or a key your client sends.</p><p>If the store claimed the key but the run was never created (for example <code>createRun</code> failed right after the claim), the next dispatch with that key creates the run under the reserved id. <code>createRun</code> is insert-if-absent, so concurrent dispatches create it once.</p><h2 id="concurrency-keys" tabindex="-1">Concurrency keys <a class="header-anchor" href="#concurrency-keys" aria-label="Permalink to &quot;Concurrency keys&quot;">​</a></h2><p>A run with a <code>concurrencyKey</code> starts only when no other run of the same agent with the same key is <code>running</code>, <code>waiting</code> or <code>interrupted</code>. Runs with different keys, and runs without a key, run in parallel up to the engine&#39;s <code>maxConcurrentRuns</code>. See <a href="/guide/concurrency">Concurrency, Leases &amp; Multi-Replica</a>.</p><p>Typical keys: one per repository, issue or pull request (<code>acme/app#42</code>), or one per mailbox.</p>`,28)])])}const E=e(t,[["render",p]]);export{y as __pageData,E as default};
